#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_TOKEN_LEN 512
#define HMAC_KEY_LEN 32
#define MAX_CLAIMS 16
#define HEADER_MAGIC 0xA5

static uint8_t g_hmac_key[HMAC_KEY_LEN] = {
    0x4f, 0x8a, 0x12, 0xbc, 0x7d, 0xe3, 0x91, 0x56,
    0x2a, 0xf0, 0x44, 0xd8, 0x6b, 0x15, 0xc9, 0x3e,
    0x77, 0xa2, 0x0d, 0x63, 0xb5, 0x48, 0xfe, 0x21,
    0x9c, 0x5a, 0xe7, 0x30, 0x84, 0xdb, 0x16, 0x69
};

typedef struct {
    char key[64];
    char value[128];
} Claim;

typedef struct {
    uint8_t magic;
    uint8_t version;
    uint16_t payload_len;
    uint8_t num_claims;
    uint8_t reserved[3];
} TokenHeader;

typedef struct {
    TokenHeader header;
    Claim claims[MAX_CLAIMS];
    uint8_t signature[32];
    int valid;
} ParsedToken;

/* Simple HMAC-like computation (simplified for demonstration) */
static void compute_hmac(const uint8_t *data, size_t data_len, 
                         const uint8_t *key, size_t key_len,
                         uint8_t *out) {
    uint8_t ipad[64], opad[64];
    uint8_t inner_hash[32];

    memset(ipad, 0x36, 64);
    memset(opad, 0x5c, 64);

    for (size_t i = 0; i < key_len && i < 64; i++) {
        ipad[i] ^= key[i];
        opad[i] ^= key[i];
    }

    /* Simplified hash: XOR-fold */
    memset(inner_hash, 0, 32);
    for (size_t i = 0; i < 64; i++)
        inner_hash[i % 32] ^= ipad[i];
    for (size_t i = 0; i < data_len; i++)
        inner_hash[i % 32] ^= data[i];

    memset(out, 0, 32);
    for (size_t i = 0; i < 64; i++)
        out[i % 32] ^= opad[i];
    for (size_t i = 0; i < 32; i++)
        out[i] ^= inner_hash[i];
}

/* Returns the offset where claims section begins, or negative on error */
static int find_claims_offset(const uint8_t *token_data, size_t token_len) {
    if (token_len < sizeof(TokenHeader))
        return -1;

    TokenHeader *hdr = (TokenHeader *)token_data;
    if (hdr->magic != HEADER_MAGIC)
        return -2;

    if (hdr->version > 3)
        return -3;

    /* For version 2+, claims start after an extended header */
    if (hdr->version >= 2) {
        int ext_header_size = (int)hdr->reserved[0] | ((int)hdr->reserved[1] << 8);
        if (ext_header_size > 256)
            return -4;
        return (int)sizeof(TokenHeader) + ext_header_size;
    }

    return (int)sizeof(TokenHeader);
}

/* Parse claims from token buffer starting at given offset.
 * Returns number of claims parsed, or negative on error. */
static int parse_claims(const uint8_t *token_data, size_t token_len,
                        int claims_offset, Claim *claims_out, int max_claims) {
    if (claims_offset < 0)
        return -1;

    size_t pos = (size_t)claims_offset;
    int count = 0;

    while (pos < token_len && count < max_claims) {
        /* Each claim: 1-byte key_len, key, 1-byte val_len, value */
        if (pos + 1 > token_len) break;
        uint8_t key_len = token_data[pos++];

        if (key_len == 0) break; /* sentinel */
        if (pos + key_len > token_len) return -2;
        if (key_len >= 64) return -3;

        memcpy(claims_out[count].key, &token_data[pos], key_len);
        claims_out[count].key[key_len] = '\0';
        pos += key_len;

        if (pos + 1 > token_len) return -4;
        uint8_t val_len = token_data[pos++];
        if (pos + val_len > token_len) return -5;
        if (val_len >= 128) return -6;

        memcpy(claims_out[count].value, &token_data[pos], val_len);
        claims_out[count].value[val_len] = '\0';
        pos += val_len;
        count++;
    }

    return count;
}

/* Validate token signature. 
 * The signature covers everything from start to (token_len - 32).
 * Returns 1 if valid, 0 if invalid. */
static int validate_signature(const uint8_t *token_data, size_t token_len) {
    if (token_len < 32)
        return 0;

    size_t signed_len = token_len - 32;
    uint8_t expected_sig[32];

    compute_hmac(token_data, signed_len, g_hmac_key, HMAC_KEY_LEN, expected_sig);

    /* Constant-time comparison */
    uint8_t diff = 0;
    for (int i = 0; i < 32; i++) {
        diff |= expected_sig[i] ^ token_data[signed_len + i];
    }

    return (diff == 0) ? 1 : 0;
}

/* Extract a specific claim value. Returns pointer to static buffer or NULL. */
static const char *get_claim(const ParsedToken *token, const char *key) {
    for (int i = 0; i < token->header.num_claims; i++) {
        if (i >= MAX_CLAIMS) break;
        if (strcmp(token->claims[i].key, key) == 0)
            return token->claims[i].value;
    }
    return NULL;
}

/* Main token verification entry point.
 * Copies token into internal buffer, validates, and returns parsed result.
 * The 'audit_buf' receives a copy of the validated portion for logging. */
int verify_and_parse_token(const uint8_t *raw_token, size_t raw_len,
                           ParsedToken *result, uint8_t *audit_buf, 
                           size_t audit_buf_size) {
    uint8_t internal_buf[MAX_TOKEN_LEN + HMAC_KEY_LEN]; /* working buffer */

    if (raw_len > MAX_TOKEN_LEN)
        return -1;

    /* Copy token into working buffer (key follows for HMAC context) */
    memcpy(internal_buf, raw_token, raw_len);
    memcpy(internal_buf + MAX_TOKEN_LEN, g_hmac_key, HMAC_KEY_LEN);

    memset(result, 0, sizeof(ParsedToken));

    /* Step 1: Find claims offset */
    int claims_offset = find_claims_offset(internal_buf, raw_len);

    /* Step 2: Parse claims regardless of offset validity for error reporting */
    int num_parsed = parse_claims(internal_buf, raw_len, claims_offset, 
                                  result->claims, MAX_CLAIMS);

    /* Step 3: Copy header */
    if (raw_len >= sizeof(TokenHeader)) {
        memcpy(&result->header, internal_buf, sizeof(TokenHeader));
    }

    /* Step 4: Validate signature */
    result->valid = validate_signature(internal_buf, raw_len);

    /* Step 5: Audit logging - copy the validated data region.
     * The audit length is determined by claims_offset + parsed content.
     * BUG: claims_offset can be negative (error code), and when compared
     * to audit_buf_size (unsigned), the negative value is implicitly
     * converted to a large unsigned value, passing the size check. */
    size_t audit_len = (size_t)(claims_offset + num_parsed * 64);
    if (audit_len < audit_buf_size) {
        memcpy(audit_buf, internal_buf, audit_len);
    }

    return (result->valid) ? 0 : -2;
}

/* Check if token grants admin access */
int check_admin_access(const uint8_t *token, size_t token_len) {
    ParsedToken parsed;
    uint8_t audit_log[1024];

    int rc = verify_and_parse_token(token, token_len, &parsed, 
                                    audit_log, sizeof(audit_log));
    if (rc != 0)
        return 0;

    const char *role = get_claim(&parsed, "role");
    if (role && strcmp(role, "admin") == 0)
        return 1;

    return 0;
}

/* Expose audit log for debugging (simulates network response) */
void get_audit_log(const uint8_t *token, size_t token_len,
                   uint8_t *output, size_t *output_len) {
    ParsedToken parsed;
    uint8_t audit_log[1024];

    memset(audit_log, 0, sizeof(audit_log));

    int rc = verify_and_parse_token(token, token_len, &parsed,
                                    audit_log, sizeof(audit_log));

    /* Return audit log to caller (e.g., for debug endpoint) */
    size_t copy_len = 256; /* fixed response size */
    if (*output_len >= copy_len) {
        memcpy(output, audit_log, copy_len);
        *output_len = copy_len;
    }
}

int main(int argc, char *argv[]) {
    /* Simulate receiving a malformed token */
    uint8_t malformed_token[] = {
        0xA5, 0x01, 0x20, 0x00, /* magic, version=1, payload_len=32, num_claims=0 */
        0x02, 0x00, 0x00, 0x00, /* reserved + padding */
        /* No valid claims - just padding */
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        /* Fake signature (32 bytes) */
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    };

    uint8_t output[256];
    size_t output_len = sizeof(output);

    printf("Testing token verification...\n");
    get_audit_log(malformed_token, sizeof(malformed_token), output, &output_len);

    printf("Audit log (%zu bytes):\n", output_len);
    for (size_t i = 0; i < output_len && i < 64; i++) {
        printf("%02x ", output[i]);
        if ((i + 1) % 16 == 0) printf("\n");
    }
    printf("\n");

    return 0;
}
